useEffect(() => {
  const fetchStories = async () => {
    setLoading(true);
    setError(false);

    try {
      let categoryId = '';

      if (category) {
        if (isNaN(category)) {
          const catRes = await fetch(`/wp-json/wp/v2/categories?slug=${category}`);

          if (catRes.ok) {
            const catData = await catRes.json();
            if (catData.length > 0) {
              categoryId = catData[0].id;
            }
          }
        } else {
          categoryId = category;
        }
      }

      const categoryQuery = categoryId ? `&categories=${categoryId}` : '';

      const response = await fetch(
        `/wp-json/wp/v2/posts?per_page=${postsPerPage}&_embed=1${categoryQuery}&orderby=date&order=desc&page=${currentPage}`
      );

      if (!response.ok) {
        throw new Error(`Failed to fetch stories, status code: ${response.status}`);
      }

      const data = await response.json();
      const totalPagesHeader = response.headers.get('X-WP-TotalPages');

      setStories(data);
      setTotalPages(Number(totalPagesHeader) || 1);
    } catch (error) {
      console.error('Error fetching stories:', error);
      setStories([]);
      setError(true);
    } finally {
      setLoading(false);
    }
  };

  fetchStories();
}, [currentPage]);
